using System;using System.Drawing;using System.Drawing.Drawing2D;using System.Drawing.Imaging;using System.IO;using System.Collections.Generic;
class BuildIcon {
 static GraphicsPath Round(float x,float y,float w,float h,float r){var p=new GraphicsPath();p.AddArc(x,y,r*2,r*2,180,90);p.AddArc(x+w-2*r,y,r*2,r*2,270,90);p.AddArc(x+w-2*r,y+h-2*r,r*2,r*2,0,90);p.AddArc(x,y+h-2*r,r*2,r*2,90,90);p.CloseFigure();return p;}
 static void Fill(Graphics g,Color c,float x,float y,float w,float h,float r){using(var p=Round(x,y,w,h,r))using(var b=new SolidBrush(c))g.FillPath(b,p);}
 static Bitmap Render(){var b=new Bitmap(1024,1024);using(var g=Graphics.FromImage(b)){g.SmoothingMode=SmoothingMode.AntiAlias;g.ScaleTransform(4,4);using(var p=Round(8,8,240,240,58))using(var brush=new LinearGradientBrush(new Point(0,8),new Point(0,248),Color.FromArgb(28,48,75),Color.FromArgb(11,19,33)))g.FillPath(brush,p);var cyan=Color.FromArgb(78,216,233);Fill(g,Color.FromArgb(11,19,33),43,55,170,126,17);using(var p=Round(43,55,170,126,17))using(var pen=new Pen(cyan,13))g.DrawPath(pen,p);Fill(g,cyan,72,118,23,38,5);Fill(g,Color.FromArgb(255,205,65),116,97,23,59,5);Fill(g,Color.FromArgb(255,77,98),160,76,23,80,5);using(var pen=new Pen(cyan,13)){pen.StartCap=LineCap.Round;pen.EndCap=LineCap.Round;g.DrawLine(pen,128,187,128,212);g.DrawLine(pen,92,212,164,212);}}return b;}
 static void Main(string[] args){int[] sizes={16,20,24,32,40,48,64,128,256};var data=new List<byte[]>();using(var master=Render()){foreach(int size in sizes){using(var b=new Bitmap(size,size))using(var g=Graphics.FromImage(b)){g.InterpolationMode=InterpolationMode.HighQualityBicubic;g.PixelOffsetMode=PixelOffsetMode.HighQuality;g.DrawImage(master,new Rectangle(0,0,size,size));using(var m=new MemoryStream()){b.Save(m,ImageFormat.Png);data.Add(m.ToArray());}if(size==256)b.Save(Path.Combine(args[0],"App-preview.png"),ImageFormat.Png);}}}using(var w=new BinaryWriter(File.Create(Path.Combine(args[0],"App.ico")))){w.Write((ushort)0);w.Write((ushort)1);w.Write((ushort)sizes.Length);int offset=6+16*sizes.Length;for(int i=0;i<sizes.Length;i++){w.Write((byte)(sizes[i]==256?0:sizes[i]));w.Write((byte)(sizes[i]==256?0:sizes[i]));w.Write((byte)0);w.Write((byte)0);w.Write((ushort)1);w.Write((ushort)32);w.Write(data[i].Length);w.Write(offset);offset+=data[i].Length;}foreach(var bytes in data)w.Write(bytes);}}
}